select s.country, case when s.rating >= 4.1 then 'high' when s.rating >= 1.5 then 'mid' else 'low' end as rating_bucket, max(ss.units) as max_units, count(ss.revenue) as revenue_count from store_sales ss inner join products p on p.id = ss.product_id inner join suppliers s on p.supplier_id = s.id group by s.country, case when s.rating >= 4.1 then 'high' when s.rating >= 1.5 then 'mid' else 'low' end;
